Here is the root cause:
Integer overflows in ipc_validate_msg() when computing expected message sizes from attacker-controlled fields (payload_sz, ngroups) using unsigned int arithmetic without overflow checks, and signed multiplication with ngroups leading to huge size_t values. This allows bypassing size validation and leads to downstream memory corruption.

Here is the patch:
 #include <linux/socket.h>
 #include <linux/workqueue.h>
+#include <linux/overflow.h>

 #include "vfs_cache.h"

 static int ipc_validate_msg(struct ipc_msg_table_entry *entry)
 {
 	unsigned int msg_sz = entry->msg_sz;

 	switch (entry->type) {
 	case KSMBD_EVENT_RPC_REQUEST:
 	{
 		struct ksmbd_rpc_command *resp = entry->response;

-		msg_sz = sizeof(struct ksmbd_rpc_command) + resp->payload_sz;
+		if (check_add_overflow(sizeof(struct ksmbd_rpc_command),
+				       resp->payload_sz, &msg_sz))
+			return -EINVAL;
 		break;
 	}
 	case KSMBD_EVENT_SPNEGO_AUTHEN_REQUEST:
 	{
 		struct ksmbd_spnego_authen_response *resp = entry->response;

 		msg_sz = sizeof(struct ksmbd_spnego_authen_response) +
 				resp->session_key_len + resp->spnego_blob_len;
 		break;
 	}
 	case KSMBD_EVENT_SHARE_CONFIG_REQUEST:
 	{
 		struct ksmbd_share_config_response *resp = entry->response;

 		if (resp->payload_sz) {
 			if (resp->payload_sz < resp->veto_list_sz)
 				return -EINVAL;

-			msg_sz = sizeof(struct ksmbd_share_config_response) +
-					resp->payload_sz;
+			if (check_add_overflow(sizeof(struct ksmbd_share_config_response),
+					       resp->payload_sz, &msg_sz))
+				return -EINVAL;
 		}
 		break;
 	}
 	case KSMBD_EVENT_LOGIN_REQUEST_EXT:
 	{
 		struct ksmbd_login_response_ext *resp = entry->response;

 		if (resp->ngroups) {
+			if (resp->ngroups < 0 ||
+			    resp->ngroups > NGROUPS_MAX) {
+				pr_err("ngroups(%d) from login response exceeds max groups(%d)\n",
+				       resp->ngroups, NGROUPS_MAX);
+				return -EINVAL;
+			}
 			msg_sz = sizeof(struct ksmbd_login_response_ext) +
 					resp->ngroups * sizeof(gid_t);
 		}
 	}
 	}

 	return entry->msg_sz != msg_sz ? -EINVAL : 0;
 }



